import{_ as n,o as e,c as r,ab as t}from"./chunks/framework.DQy4ijAa.js";const d=JSON.parse('{"title":"LangChain","description":"","frontmatter":{},"headers":[],"relativePath":"ai/langChain/index.md","filePath":"ai/langChain/index.md","lastUpdated":1773124494000}'),l={name:"ai/langChain/index.md"};function i(o,a,h,c,s,p){return e(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="langchain" tabindex="-1">LangChain <a class="header-anchor" href="#langchain" aria-label="Permalink to &quot;LangChain&quot;">​</a></h1><p>官网地址：<a href="https://www.langchain.com/langchain" target="_blank" rel="noreferrer">https://www.langchain.com/langchain</a></p><p>官网文档：<a href="https://python.langchain.com/docs/introduction/" target="_blank" rel="noreferrer">https://python.langchain.com/docs/introduction/</a></p><p>API文档：<a href="https://python.langchain.com/api_reference/" target="_blank" rel="noreferrer">https://python.langchain.com/api_reference/</a></p><p>github地址：<a href="https://github.com/langchain-ai/langchain" target="_blank" rel="noreferrer">https://github.com/langchain-ai/langchain</a></p><p>LangChain是 2022年10月 ，由哈佛大学的 Harrison Chase （哈里森·蔡斯）发起研发的一个开源框架， 用于开发由大语言模型（LLMs）驱动的应用程序。 比如，搭建“智能体”（Agent）、问答系统（QA）、对话机器人、文档搜索系统、企业私有知识库 等</p><p><em><strong>简单来说</strong></em></p><p>LangChain ≠ LLMs</p><p>LangChain 之于 LLMs，类似 Spring 之于 Java</p><p>LangChain 之于 LLMs，类似 Django、Flask 之于 Python</p><h2 id="langchain-优势" tabindex="-1">langChain 优势 <a class="header-anchor" href="#langchain-优势" aria-label="Permalink to &quot;langChain 优势&quot;">​</a></h2><p>在大语言模型（LLM）如 ChatGPT、Claude、DeepSeek 等快速发展的今天，开发者不仅希望能“使 用”这些模型，还希望能 将它们灵活集成到自己的应用中 ，实现更强大的对话能力、检索增强生成 （RAG）、工具调用（Tool Calling）、多轮推理等功能。</p><ul><li>简化开发难度：更简单、更高效、效果更好</li><li>学习成本更低：不同模型的API不同，调用方式也有区别，切换模型时学习成本高。使用</li><li>LangChain，可以以统一、规范的方式进行调用，有更好的移植性。 现成的链式组装：LangChain提供了一些 现成的链式组装 ，用于完成特定的高级任务。让复杂的逻 辑变得 结构化、易组合、易扩展</li></ul><h2 id="langchain-架构" tabindex="-1">langChain 架构 <a class="header-anchor" href="#langchain-架构" aria-label="Permalink to &quot;langChain 架构&quot;">​</a></h2><h3 id="langchain-详情" tabindex="-1">langChain 详情 <a class="header-anchor" href="#langchain-详情" aria-label="Permalink to &quot;langChain 详情&quot;">​</a></h3><h1 id="常用工具" tabindex="-1">常用工具 <a class="header-anchor" href="#常用工具" aria-label="Permalink to &quot;常用工具&quot;">​</a></h1><h2 id="调用推荐平台" tabindex="-1">调用推荐平台 <a class="header-anchor" href="#调用推荐平台" aria-label="Permalink to &quot;调用推荐平台&quot;">​</a></h2><p><a href="https://www.closeai-asia.com" target="_blank" rel="noreferrer">closeai</a></p><hr><h1 id="langchain调用本地模型" tabindex="-1">LangChain调用本地模型 <a class="header-anchor" href="#langchain调用本地模型" aria-label="Permalink to &quot;LangChain调用本地模型&quot;">​</a></h1><h2 id="ollama的介绍" tabindex="-1">Ollama的介绍 <a class="header-anchor" href="#ollama的介绍" aria-label="Permalink to &quot;Ollama的介绍&quot;">​</a></h2><p>Ollama是在Github上的一个开源项目，其项目定位是：<strong>一个本地运行大模型的集成框架</strong>。目前主要针 对主流的LlaMA架构的开源大模型设计，可以实现如 Qwen、Deepseek 等主流大模型的下载、启动和 本地运行的自动化部署及推理流程。</p><p>目前作为一个非常热门的大模型托管平台，已被包括LangChain、Taskweaver等在内的多个热门项目高 度集成。</p><p>Ollama官方地址：<a href="https://ollama.com" target="_blank" rel="noreferrer">https://ollama.com</a></p><hr><h1 id="常见术语" tabindex="-1">常见术语 <a class="header-anchor" href="#常见术语" aria-label="Permalink to &quot;常见术语&quot;">​</a></h1><h2 id="token是什么" tabindex="-1">Token是什么？ <a class="header-anchor" href="#token是什么" aria-label="Permalink to &quot;Token是什么？&quot;">​</a></h2><p><strong>基本单位</strong> : 大模型处理文本的最小单位是token（相当于自然语言中的词或字），输出时逐个token 依次生成。</p><p><strong>收费依据</strong> ：大语言模型(LLM)通常也是以token的数量作为其计量(或收费)的依据。</p><ul><li>1个Token≈1-1.8个汉字，1个Token≈3-4个英文字母</li><li>Token与字符转化的可视化工具： <ul><li>OpenAI提供：<a href="https://platform.openai.com/tokenizer" target="_blank" rel="noreferrer">https://platform.openai.com/tokenizer</a></li><li>百度智能云提供：<a href="https://console.bce.baidu.com/support/#/tokenizer" target="_blank" rel="noreferrer">https://console.bce.baidu.com/support/#/tokenizer</a></li></ul></li></ul><p><strong>max_tokens设置建议</strong>：</p><ul><li>客服短回复：128-256。比如：生成一句客服回复（如“订单已发货，预计明天送达”）</li><li>常规对话、多轮对话：512-1024</li><li>长内容生成：1024-4096。比如：生成一篇产品说明书（包含功能、使用方法等结构）</li></ul>',32)])])}const m=n(l,[["render",i]]);export{d as __pageData,m as default};
